(5781315, 841112, 60173, '<td valign="top">One thing that bothers me about this shot is the crop on "Never forgotten" making it "Ever forgotten". I know it probably wasn''t your intention, but it''s mighty distracting and defeats the purpose of the shot.</td>', 'One thing that bothers me about this shot is the crop on "Never forgotten" making it "Ever forgotten". I know it probably wasn''t your intention, but it''s mighty distracting and defeats the purpose of the shot.', '2009-12-26 00:09:28.000000', NULL, 1),
(5781318, 841255, 60173, '<td valign="top">A couple months ago I processed a shot very similarly, but knew it was lacking the human element. Your photo has everything mine was lacking. The dappled lighting on your model is fantastic. Truly an inspiration.</td>', 'A couple months ago I processed a shot very similarly, but knew it was lacking the human element. Your photo has everything mine was lacking. The dappled lighting on your model is fantastic. Truly an inspiration.', '2009-12-26 00:14:41.000000', NULL, 1),
